export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * Copilot Runtime for this harness.\n *\n * Shape comes from the Angular quickstart's Node runtime server\n * (https://docs.copilotkit.ai/angular/ag2/quickstart), with the agent swapped\n * for the `Ag2Agent` binding from `@ag-ui/ag2` — the Angular/AG2 quickstart\n * defers the backend step to \"register this backend as the `default` agent\".\n *\n * `Ag2Agent` is a thin subclass of the generic AG-UI `HttpAgent`: AG2's\n * `AGUIStream` serves the AG-UI protocol directly over SSE, so the runtime\n * simply POSTs to the mount in backend/main.py.\n *\n * `default` and `support` resolve to the same AG2 process. `support` exists so\n * the doc snippets that use `agentId=\"support\"` (Chat UI, Threads) run verbatim.\n * `subagents` is the Sub-Agents supervisor, a separate AG2 process\n * (backend/subagents/main.py) — the key and `/subagents` path the showcase uses.\n *\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\n * https://docs.copilotkit.ai/angular/ag2/backend/copilot-runtime\n *\n * `intelligence` puts the main runtime in Intelligence mode, which is what\n * serves the thread and memory endpoints the Threads guide's surfaces read.\n */\nimport { createServer } from \"node:http\";\nimport { fileURLToPath } from \"node:url\";\nimport { CopilotKitIntelligence, CopilotRuntime } from \"@copilotkit/runtime/v2\";\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\nimport { Ag2Agent } from \"@ag-ui/ag2\";\n\n/**\n * Nothing loads a `.env` for this process: the root `.env` is read only by\n * backend/main.py (python-dotenv), and it holds the model key, which never\n * reaches the runtime. `CPK_INTELLIGENCE_API_KEY` therefore lives in\n * `frontend/.env`, and the runtime loads that file itself before constructing\n * the Intelligence client.\n *\n * `process.loadEnvFile` is Node's own loader (>= 20.12) and never overrides a\n * variable the shell already exported. The path is resolved from\n * `import.meta.url` so it does not depend on the cwd, and the call is guarded\n * so a missing `.env` leaves dev running instead of crashing.\n */\ntry {\n  process.loadEnvFile(fileURLToPath(new URL(\".env\", import.meta.url)));\n} catch {\n  // No .env next to this file — fall back to whatever the shell exported.\n}\n\n// backend/main.py mounts AGUIStream at /weather. Starlette redirects the\n// slash-less form, so the trailing slash is load-bearing.\nconst agentUrl =\n  process.env[\"AG2_AGENT_URL\"] ?? \"http://localhost:8000/weather/\";\n\n// backend/subagents/main.py mounts the supervisor at /subagents; same\n// trailing-slash rule.\nconst subagentsUrl =\n  process.env[\"AG2_SUBAGENTS_URL\"] ?? \"http://localhost:8001/subagents/\";\n\n/**\n * CopilotKit Intelligence client.\n * https://docs.copilotkit.ai/intelligence/connect-your-runtime\n *\n * `apiKey` is the only required field — the key scopes the project. `apiUrl`\n * and `wsUrl` are deliberately left unset so both planes point at the managed\n * platform; that page is explicit that they are overridden together or not at\n * all, because the REST and realtime planes live on different hosts.\n */\nconst intelligence = new CopilotKitIntelligence({\n  apiKey: process.env[\"CPK_INTELLIGENCE_API_KEY\"]!,\n});\n\nconst runtime = new CopilotRuntime({\n  agents: {\n    default: new Ag2Agent({ url: agentUrl }),\n    support: new Ag2Agent({ url: agentUrl }),\n    subagents: new Ag2Agent({ url: subagentsUrl }),\n  },\n  // auth : forward identity deliberately start\n  forwardHeaders: {\n    allow: [\"authorization\", \"x-tenant-id\"],\n  },\n  // auth : forward identity deliberately end\n  a2ui: {},\n  // Passing `intelligence` (never `runner` — the two cannot be combined) is\n  // what puts this runtime in Intelligence mode. An SSE runtime replies in the\n  // browser exactly the same way with the credential never read.\n  intelligence,\n  /**\n   * LOCAL PLACEHOLDER — NOT AN AUTHENTICATION CHECK.\n   *\n   * Threads are per-user, and the runtime options type requires\n   * `identifyUser` for any runtime serving a web surface. This harness has no\n   * login, and the browser sends no `x-user-id` / `x-user-name` header, so in\n   * practice every local visitor falls through to the same constant id and\n   * shares one thread history. That is acceptable for a local doc harness and\n   * for nothing else.\n   *\n   * In production, resolve the user from a server-verified session or bearer\n   * token on `request` and THROW on an unauthenticated request. Never trust a\n   * caller-supplied id header: anyone can set one and read another user's\n   * threads.\n   */\n  identifyUser: (request) => ({\n    id: request.headers.get(\"x-user-id\") ?? \"local-harness-user\",\n    name: request.headers.get(\"x-user-name\") ?? \"Local harness user\",\n  }),\n  /**\n   * Memory is opt-in even in Intelligence mode: without this every\n   * `/memories/*` request 404s and `injectMemories().isAvailable()` stays\n   * false. `access` runs per request, for the agent and for the browser\n   * (`consumer`), and grants each scope separately.\n   *\n   * LOCAL PLACEHOLDER, like `identifyUser` above: a constant grant for every\n   * caller. In production, derive it from the verified `user`.\n   */\n  memory: {\n    access: () => ({ user: \"read-write\", project: \"read\" }),\n  },\n});\n\nconst port = Number(process.env[\"PORT\"] ?? 8200);\n\n/**\n * Credentialed CORS, from the Authentication guide's \"Send cookies to a\n * cross-origin runtime\": the app sets `credentials: \"include\"`, so the runtime\n * must answer with `credentials: true` and the app's exact origins — never\n * `*`. These are the two origins this repo serves the app from: `ng serve`\n * (package.json `start`) and the built SSR server (src/server.ts).\n *\n * `allowHeaders` is listed because its default is `[\"*\"]`, which browsers take\n * literally on credentialed requests — so JSON POSTs and the `Authorization`\n * header would fail their preflight. It holds what the client sends\n * (`content-type`, `authorization`), the license header `provideCopilotKit`\n * adds when a key is set, and the `x-tenant-id` the forwardHeaders allowlist\n * names.\n */\nconst cors = {\n  origin: [\"http://localhost:4200\", \"http://localhost:4000\"],\n  credentials: true,\n  allowHeaders: [\n    \"content-type\",\n    \"authorization\",\n    \"x-copilotcloud-public-api-key\",\n    \"x-tenant-id\",\n  ],\n};\n\n// auth : authenticated runtime start\n/**\n * A second runtime for the /auth demo, gated by the Authentication guide's\n * `onRequest` hook. It is separate — as in the CopilotKit showcase's\n * `/api/copilotkit-auth` route — because gating the main runtime would answer\n * 401 to every other route in this harness.\n *\n * The guide's `createCopilotExpressHandler` is swapped for the\n * `createCopilotNodeListener` this server already uses; both take the same\n * `hooks` option. `verifySession` is not defined by the guide: it is the\n * showcase's static demo-token check. Never use a hard-coded shared secret\n * for real auth.\n */\nconst DEMO_TOKEN = \"demo-token-123\";\n\nasync function verifySession(token: string) {\n  return token === DEMO_TOKEN ? { token } : null;\n}\n\nconst authRuntime = new CopilotRuntime({\n  agents: {\n    default: new Ag2Agent({ url: agentUrl }),\n  },\n});\n\nconst authListener = createCopilotNodeListener({\n  runtime: authRuntime,\n  basePath: \"/api/copilotkit-auth\",\n  cors,\n  hooks: {\n    onRequest: async ({ request }) => {\n      const token = request.headers\n        .get(\"authorization\")\n        ?.replace(/^Bearer\\s+/i, \"\");\n      const session = token ? await verifySession(token) : null;\n\n      if (!session) {\n        throw new Response(\"Unauthorized\", { status: 401 });\n      }\n    },\n  },\n});\n// auth : authenticated runtime end\n\nconst listener = createCopilotNodeListener({\n  runtime,\n  basePath: \"/api/copilotkit\",\n  cors,\n});\n\ncreateServer((req, res) =>\n  req.url?.startsWith(\"/api/copilotkit-auth\")\n    ? authListener(req, res)\n    : listener(req, res),\n).listen(port, () => {\n  console.log(\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\n  );\n  console.log(\n    `Authenticated runtime listening at http://localhost:${port}/api/copilotkit-auth`,\n  );\n  console.log(`AG2 agent: ${agentUrl}`);\n  console.log(`AG2 sub-agents supervisor: ${subagentsUrl}`);\n});\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular/ag2/quickstart */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* ------------------------------------------------------------------ */\n/* Chat UI guide — \"Scope CSS changes\"                                 */\n/* https://docs.copilotkit.ai/angular/ag2/guides/chat-ui              */\n/* ------------------------------------------------------------------ */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n\n/* ------------------------------------------------------------------ */\n/* A2UI guide — \"Style rendered components\"                            */\n/* https://docs.copilotkit.ai/angular/ag2/guides/a2ui                 */\n/* ------------------------------------------------------------------ */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: white;\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: #eef2ff;\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: #dcfce7;\n  color: #166534;\n}\n.a2ui-status-warning {\n  background: #fef3c7;\n  color: #92400e;\n}\n.a2ui-status-error {\n  background: #fee2e2;\n  color: #991b1b;\n}\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { routes } from './app.routes';\n\n/**\n * Host function exposed to sandboxed Open Generative UI, verbatim from\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n */\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\n  name: 'setDashboardFilter',\n  description: 'Set the active dashboard filter',\n  parameters: z.object({ filter: z.string() }),\n  handler: async ({ filter }) => {\n    sessionStorage.setItem('dashboard-filter', filter);\n    return { applied: filter };\n  },\n};\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never talks to the AG2 agent directly.\n * The `Ag2Agent` binding itself lives server-side in frontend/server.ts.\n *\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\n * a catalog is added. See README known issues.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8200/api/copilotkit',\n      // auth : send cookies to a cross-origin runtime start\n      credentials: 'include',\n      // auth : send cookies to a cross-origin runtime end\n      a2ui: {\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      openGenerativeUI: {\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\n        // written. Cast at the array site, the same idiom the docs use for the\n        // equivalent `component` variance problem. See README known issues.\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\n      },\n    }),\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "/**\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\n * A2UI renderer activates automatically. No extra configuration is needed.\"\n *\n * The recovery thresholds the guide prescribes are set once in\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\n * https://docs.copilotkit.ai/angular/ag2/guides/a2ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class A2uiChatComponent {}\n",
  "src/app/features/attachments/media-chat.component.ts": "/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n}\n",
  "src/app/features/auth/auth-card.ts": "/**\n * Sign-in / sign-out card for\n * https://docs.copilotkit.ai/angular/ag2/auth\n *\n * `AuthCardComponent` from the Angular Showcase's\n * features/app-settings/app-settings-cards.ts, unchanged. The agent-config\n * card in that file belongs to a different demo and is left out.\n */\nimport {\n  ChangeDetectionStrategy,\n  Component,\n  input,\n  output,\n} from \"@angular/core\";\n\n@Component({\n  selector: \"showcase-auth-card\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    @if (authenticated()) {\n      <div\n        class=\"auth-banner authenticated\"\n        data-testid=\"auth-banner\"\n        data-authenticated=\"true\"\n      >\n        <span data-testid=\"auth-status\">✓ Signed in as demo user</span>\n        <button\n          type=\"button\"\n          data-testid=\"auth-sign-out-button\"\n          (click)=\"signOut.emit()\"\n        >\n          Sign out\n        </button>\n      </div>\n    } @else {\n      <article class=\"sign-in-card\" data-testid=\"auth-sign-in-card\">\n        <p class=\"eyebrow\">Request authentication</p>\n        <h1>Sign in to start chatting</h1>\n        <p>\n          This runtime rejects requests without an\n          <code>Authorization</code> header. Signing in mounts chat with a scoped\n          demo bearer token.\n        </p>\n        <div class=\"token-row\">\n          <span>Demo token</span>\n          <code data-testid=\"auth-demo-token\">demo-token-123</code>\n        </div>\n        <p class=\"security-note\">\n          Real applications should issue per-user tokens through an identity\n          provider and keep shared secrets off the client.\n        </p>\n        <button\n          type=\"button\"\n          data-testid=\"auth-sign-in-button\"\n          (click)=\"signIn.emit()\"\n        >\n          Sign in with demo token\n        </button>\n      </article>\n    }\n  `,\n  styles: `\n    :host {\n      display: block;\n    }\n    .sign-in-card {\n      width: min(100%, 28rem);\n      padding: 1.5rem;\n      border: 1px solid #d8e0ea;\n      border-radius: 1rem;\n      color: #17233a;\n      background: #fff;\n      box-shadow: 0 18px 48px rgb(30 49 73 / 12%);\n    }\n    .eyebrow {\n      margin: 0;\n      color: #4f46e5;\n      font-size: 0.7rem;\n      font-weight: 750;\n      letter-spacing: 0.14em;\n      text-transform: uppercase;\n    }\n    h1 {\n      margin: 0.35rem 0 0.7rem;\n      font-size: 1.45rem;\n    }\n    p {\n      color: #52637a;\n      line-height: 1.55;\n    }\n    code {\n      padding: 0.15rem 0.35rem;\n      border-radius: 0.3rem;\n      background: #eef2ff;\n      font-family: ui-monospace, monospace;\n    }\n    .token-row {\n      display: grid;\n      gap: 0.4rem;\n      margin: 1rem 0;\n      padding: 0.85rem;\n      border: 1px solid #d8e0ea;\n      border-radius: 0.65rem;\n      background: #f8fafc;\n    }\n    .token-row span {\n      color: #64748b;\n      font-size: 0.7rem;\n      font-weight: 700;\n      text-transform: uppercase;\n    }\n    .security-note {\n      font-size: 0.78rem;\n    }\n    button {\n      min-height: 2.65rem;\n      padding: 0.65rem 1rem;\n      border: 1px solid #3730a3;\n      border-radius: 0.65rem;\n      color: #fff;\n      background: #4f46e5;\n      font: inherit;\n      font-weight: 700;\n      cursor: pointer;\n    }\n    button:focus-visible {\n      outline: 3px solid #a5b4fc;\n      outline-offset: 2px;\n    }\n    .sign-in-card > button {\n      width: 100%;\n      margin-top: 0.4rem;\n    }\n    .auth-banner {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 1rem;\n      padding: 0.75rem 1rem;\n      border: 1px solid #86efac;\n      border-radius: 0.75rem;\n      color: #14532d;\n      background: #f0fdf4;\n      font-size: 0.85rem;\n      font-weight: 650;\n    }\n    .auth-banner button {\n      min-height: 2.25rem;\n      padding: 0.35rem 0.7rem;\n      border-color: #86efac;\n      color: #14532d;\n      background: #fff;\n    }\n  `,\n})\nexport class AuthCardComponent {\n  readonly authenticated = input.required<boolean>();\n  readonly signIn = output<void>();\n  readonly signOut = output<void>();\n}\n",
  "src/app/features/auth/auth-demo.component.ts": "/**\n * The Authentication guide's browser half, against the gated\n * `/api/copilotkit-auth` runtime in server.ts.\n * https://docs.copilotkit.ai/angular/ag2/auth\n *\n * Flow and layout follow the Angular Showcase's auth demo\n * (features/app-settings/app-settings-feature.component.ts): signed out, only\n * the sign-in card shows; signed in, the chat appears with the card above it.\n * The header update is the guide's \"When sign-in state changes after\n * bootstrap\" snippet; signing out sends `{}`, as its production checklist\n * asks.\n *\n * Harness-only: this app's one `provideCopilotKit` points at the ungated\n * runtime, so this demo also switches `runtimeUrl` to the gated one while\n * signed in, and restores the configured runtime when it signs out or leaves.\n */\nimport { Component, DestroyRef, inject, signal } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotKit,\n  injectCopilotKitConfig,\n} from '@copilotkit/angular';\n\nimport { AuthCardComponent } from './auth-card';\n\n/** The showcase's demo token, checked by `verifySession` in server.ts. */\nconst DEMO_TOKEN = 'demo-token-123';\nconst AUTH_RUNTIME_URL = 'http://localhost:8200/api/copilotkit-auth';\n\n@Component({\n  selector: 'app-auth-demo',\n  imports: [CopilotChat, AuthCardComponent],\n  template: `\n    @if (!signedIn()) {\n      <main class=\"sign-in-page\">\n        <showcase-auth-card [authenticated]=\"false\" (signIn)=\"signIn()\" />\n      </main>\n    } @else {\n      <main class=\"settings-page\">\n        <section class=\"settings-panel\">\n          <showcase-auth-card [authenticated]=\"true\" (signOut)=\"signOut()\" />\n        </section>\n        <section class=\"chat-surface\" aria-label=\"CopilotKit assistant\">\n          <copilot-chat />\n        </section>\n      </main>\n    }\n  `,\n  styles: `\n    :host {\n      display: block;\n      height: 100%;\n    }\n    .sign-in-page {\n      display: grid;\n      height: 100%;\n      min-height: 0;\n      place-items: center;\n      padding: 1.5rem;\n      background: radial-gradient(circle at 50% 20%, #eef2ff, #eef3f7 55%);\n    }\n    .settings-page {\n      display: grid;\n      height: 100%;\n      min-height: 0;\n      grid-template-rows: auto minmax(0, 1fr);\n      gap: 1rem;\n      padding: 1rem;\n      background: #eef3f7;\n    }\n    .settings-panel {\n      min-width: 0;\n    }\n    .chat-surface {\n      min-height: 0;\n      overflow: hidden;\n      border: 1px solid #d8e0ea;\n      border-radius: 1rem;\n      background: #fff;\n    }\n  `,\n})\nexport class AuthDemoComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  private readonly defaultRuntimeUrl = injectCopilotKitConfig().runtimeUrl;\n  protected readonly signedIn = signal(false);\n\n  constructor() {\n    inject(DestroyRef).onDestroy(() => this.signOut());\n  }\n\n  protected signIn(): void {\n    // Header first: switching the URL triggers discovery against the gated\n    // runtime, which must already carry the token.\n    this.updateSession(DEMO_TOKEN);\n    this.copilotKit.updateRuntime({ runtimeUrl: AUTH_RUNTIME_URL });\n    this.signedIn.set(true);\n  }\n\n  protected signOut(): void {\n    this.updateSession(null);\n    this.copilotKit.updateRuntime({ runtimeUrl: this.defaultRuntimeUrl });\n    this.signedIn.set(false);\n  }\n\n  private updateSession(sessionToken: string | null): void {\n    const copilotKit = this.copilotKit;\n    // auth : update headers after sign-in start\n    copilotKit.updateRuntime({\n      headers: sessionToken\n        ? { Authorization: `Bearer ${sessionToken}` }\n        : {},\n    });\n    // auth : update headers after sign-in end\n  }\n}\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\n *\n * The popup and the sidebar each get their own tab AND their own host\n * component. The guide declares both in a single component, but both render a\n * launcher at the same fixed coordinates, so mounting them together stacks two\n * launchers on one spot and the sidebar — rendered second — swallows every\n * click. The guide's combined component stays verbatim in\n * popup-sidebar.component.ts and is what the route page displays as source.\n *\n * Bindings on the split hosts are the guide's, unchanged.\n *\n * `.support-chat` is applied to the inline tab only. It is the scope class for\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\n * putting it on the shared host would tint the custom-message, popup, and\n * sidebar surfaces too, and each of those is meant to show its own default\n * styling.\n */\nimport { Component, signal } from '@angular/core';\n\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\nimport { PopupOnlyComponent } from './popup-only.component';\nimport { SidebarOnlyComponent } from './sidebar-only.component';\nimport { SupportChatComponent } from './support-chat.component';\n\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\n\n@Component({\n  selector: 'app-chat-ui-demo',\n  imports: [\n    SupportChatComponent,\n    CustomMessageChatComponent,\n    PopupOnlyComponent,\n    SidebarOnlyComponent,\n  ],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\n        @for (tab of tabs; track tab.id) {\n          <button\n            type=\"button\"\n            role=\"tab\"\n            [attr.aria-selected]=\"surface() === tab.id\"\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\n            [class]=\"\n              surface() === tab.id\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\n            \"\n            (click)=\"surface.set(tab.id)\"\n          >\n            {{ tab.label }}\n          </button>\n        }\n      </div>\n\n      <div class=\"min-h-0 flex-1\">\n        @switch (surface()) {\n          @case ('inline') {\n            <!-- Scope class for the guide's CSS block — this tab only. -->\n            <div class=\"support-chat h-full\">\n              <app-support-chat />\n            </div>\n          }\n          @case ('custom-message') {\n            <div class=\"h-full\">\n              <app-custom-message-chat />\n            </div>\n          }\n          @case ('popup') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-popup</code> opens from a floating launcher and\n                exposes a two-way <code>open</code> model, so the harness can\n                open it from here. It manages focus, closes on Escape, and\n                restores focus to the launcher.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\n              >\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\n              </button>\n              <app-popup-only #popupHost />\n            </div>\n          }\n          @case ('sidebar') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-sidebar</code> is docked to the right at 480px.\n                Compact viewports render it as a modal even when\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\n                docked sidebar can own the page margin at a time.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\n              >\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\n              </button>\n              <app-sidebar-only #sidebarHost />\n            </div>\n          }\n        }\n      </div>\n    </div>\n  `,\n})\nexport class ChatUiDemoComponent {\n  protected readonly surface = signal<Surface>('inline');\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\n    { id: 'inline', label: 'Inline chat' },\n    { id: 'custom-message', label: 'Custom assistant message' },\n    { id: 'popup', label: 'Popup' },\n    { id: 'sidebar', label: 'Sidebar' },\n  ];\n}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n",
  "src/app/features/chat-ui/popup-only.component.ts": "/**\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\n * Both render a launcher at the same fixed coordinates\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\n * stacks two launchers on one spot and the sidebar — rendered second — takes\n * every click. Splitting them is what makes each surface separately testable;\n * the combined component is kept verbatim in popup-sidebar.component.ts and\n * shown as the source on the route page.\n *\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-only',\n  imports: [CopilotPopup],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n  `,\n})\nexport class PopupOnlyComponent {\n  readonly popupOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "/**\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * See popup-only.component.ts for why the guide's combined component is split\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\n *\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-sidebar-only',\n  imports: [CopilotSidebar],\n  template: `\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class SidebarOnlyComponent {\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/support-chat.component.ts": "/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n",
  "src/app/features/headless/headless-chat.component.ts": "/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  readonly store = injectAgentStore('default');\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    await this.copilotKit.core.runAgent({ agent });\n  }\n}\n",
  "src/app/features/hitl/approval-card.component.ts": "/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n */\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n",
  "src/app/features/hitl/approval-tools.service.ts": "/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n */\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n  }\n}\n",
  "src/app/features/hitl/hitl-chat.component.ts": "/**\n * Puts the guide's two human-in-the-loop paths side by side: the decision tool\n * (registered by ApprovalToolsService, rendered inside the chat's tool-call\n * flow) and the headless interrupt controller (rendered outside the chat).\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n *\n * Injecting ApprovalToolsService is what constructs it, and construction is\n * what performs the `registerHumanInTheLoop` call.\n */\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\nimport { InterruptPanelComponent } from './interrupt-panel.component';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat, InterruptPanelComponent],\n  providers: [ApprovalToolsService],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <app-interrupt-panel />\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService);\n}\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "/**\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\n * renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/ag2/guides/human-in-the-loop\n */\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  protected readonly controller = injectInterrupt<ReviewRequest>({\n    agentId: 'default',\n  });\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n",
  "src/app/features/media/voice-chat.component.ts": "/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/ag2/guides/voice-multimodal\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\n  enabled: true,\n  accept: 'image/*,application/pdf',\n  maxSize: 10 * 1024 * 1024,\n};\n\n@Component({\n  selector: 'app-voice-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\n    </div>\n  `,\n})\nexport class VoiceChatComponent {\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\n}\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\n * Harness wrapper mounting the guide's memory list beside a chat, so the\n * `isAvailable()` gate can be observed against a live runtime.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { MemoryListComponent } from './memory-list.component';\n\n@Component({\n  selector: 'app-memory-demo',\n  imports: [CopilotChat, MemoryListComponent],\n  template: `\n    <div class=\"flex h-full gap-4 p-4\">\n      <section\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          injectMemories\n        </h2>\n        <app-memory-list />\n      </section>\n      <div class=\"min-w-0 flex-1\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class MemoryDemoComponent {}\n",
  "src/app/features/memory/memory-list.component.ts": "/**\n * \"Read and manage memory\", verbatim. The `isAvailable()` gate is the point of\n * the sample: a runtime may not provide the memory routes at all.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectMemories } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-memory-list',\n  template: `\n    @if (!memory.isAvailable()) {\n      <p>Memory is not available for this runtime.</p>\n    } @else {\n      @for (item of memory.memories(); track item.id) {\n        <article>\n          <p>{{ item.content }}</p>\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\n        </article>\n      }\n    }\n  `,\n})\nexport class MemoryListComponent {\n  readonly memory = injectMemories();\n\n  protected remove(id: string): void {\n    this.memory.removeMemory(id).catch(() => undefined);\n  }\n\n  protected addPreference(): void {\n    this.memory\n      .addMemory({\n        kind: 'operational',\n        content: 'Prefer concise status updates.',\n      })\n      .catch(() => undefined);\n  }\n}\n",
  "src/app/features/quickstart/quickstart-chat.ts": "/**\n * Quickstart step \"Add the chat UI\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/quickstart\n *\n * Only the selector and class name differ from the doc (which mounts this as\n * the app root); the template and imports are unchanged.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n",
  "src/app/features/shared-state/account-context.component.ts": "/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <br>\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n",
  "src/app/features/shared-state/selection-context.component.ts": "/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "/**\n * Mounts the guide's three surfaces against one chat: the read/write state\n * panel, the accessor-based context, and the directive-based context.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [\n    CopilotChat,\n    WorkspaceComponent,\n    AccountContextComponent,\n    SelectionContextComponent,\n  ],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n",
  "src/app/features/shared-state/workspace.component.ts": "/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/ag2/guides/shared-state\n */\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n    <br>\n     <button type=\"button\" (click)=\"setPriority('low')\">\n      Mark low priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n",
  "src/app/features/subagents/subagent-cards.ts": "/**\n * Sub-agent transcript card and delegation log for\n * https://docs.copilotkit.ai/angular/ag2/multi-agent/subagents\n *\n * The page renders these without showing them. This is the\n * `SubAgentActivityCard` and `DelegationLogComponent` half of the Angular\n * Showcase's features/agent-state/agent-state-cards.ts, unchanged; the planner\n * card belongs to a different demo and is left out.\n */\nimport {\n  ChangeDetectionStrategy,\n  Component,\n  computed,\n  input,\n} from \"@angular/core\";\nimport type { AngularToolCall } from \"@copilotkit/angular\";\n\nimport type { Delegation, SubAgentName } from \"./subagent-model\";\n\nconst SUB_AGENT_META: Readonly<\n  Record<\n    SubAgentName,\n    {\n      label: string;\n      testId: string;\n      delegationTestId: string;\n      action: string;\n    }\n  >\n> = {\n  research_agent: {\n    label: \"Researcher\",\n    testId: \"subagent-card-researcher\",\n    delegationTestId: \"subagent-delegation-researcher\",\n    action: \"gathering facts\",\n  },\n  writing_agent: {\n    label: \"Writer\",\n    testId: \"subagent-card-writer\",\n    delegationTestId: \"subagent-delegation-writer\",\n    action: \"drafting prose\",\n  },\n  critique_agent: {\n    label: \"Critic\",\n    testId: \"subagent-card-critic\",\n    delegationTestId: \"subagent-delegation-critic\",\n    action: \"reviewing the draft\",\n  },\n};\n\n@Component({\n  selector: \"showcase-subagent-activity-card\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article\n      class=\"subagent-card\"\n      [attr.data-testid]=\"meta().testId\"\n      [attr.data-sub-agent]=\"subAgent()\"\n      [attr.data-status]=\"toolCall().status\"\n    >\n      <header>\n        <strong>{{ meta().label }}</strong>\n        <span>{{ complete() ? \"Complete\" : \"Working\" }}</span>\n      </header>\n      <p><b>Task:</b> {{ toolCall().args.task || \"Receiving task…\" }}</p>\n      @if (complete()) {\n        <p data-testid=\"subagent-result\"><b>Result:</b> {{ toolCall().result }}</p>\n      } @else {\n        <p>{{ meta().label }} is {{ meta().action }}…</p>\n      }\n    </article>\n  `,\n  styles: `\n    :host {\n      display: block;\n      margin: 0.75rem 0;\n    }\n    .subagent-card {\n      overflow: hidden;\n      border: 1px solid #c7d2fe;\n      border-radius: 1rem;\n      color: #18253a;\n      background: #f8faff;\n      box-shadow: 0 6px 20px rgb(49 46 129 / 8%);\n    }\n    header {\n      display: flex;\n      justify-content: space-between;\n      gap: 1rem;\n      padding: 0.7rem 0.9rem;\n      border-bottom: 1px solid #dbe3f0;\n      background: #eef2ff;\n    }\n    header span {\n      color: #475569;\n      font-size: 0.7rem;\n      font-weight: 700;\n      letter-spacing: 0.08em;\n      text-transform: uppercase;\n    }\n    p {\n      margin: 0;\n      padding: 0.7rem 0.9rem;\n      white-space: pre-wrap;\n      font-size: 0.8rem;\n      line-height: 1.5;\n    }\n    p + p {\n      padding-top: 0;\n    }\n  `,\n})\nexport class SubAgentActivityCard {\n  readonly toolCall = input.required<AngularToolCall<{ task: string }>>();\n  protected readonly subAgent = computed(() => {\n    const name = this.toolCall().name;\n    return isSubAgentName(name) ? name : \"research_agent\";\n  });\n  protected readonly meta = computed(() => SUB_AGENT_META[this.subAgent()]);\n  protected readonly complete = computed(\n    () => this.toolCall().status === \"complete\",\n  );\n}\n\nfunction isSubAgentName(value: unknown): value is SubAgentName {\n  return (\n    value === \"research_agent\" ||\n    value === \"writing_agent\" ||\n    value === \"critique_agent\"\n  );\n}\n\n@Component({\n  selector: \"showcase-delegation-log\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"delegation-log\" data-testid=\"delegation-log\">\n      <header>\n        <div>\n          <p>Supervisor</p>\n          <h1>Sub-agent delegations</h1>\n        </div>\n        <span data-testid=\"delegation-count\">{{ delegations().length }} calls</span>\n      </header>\n      <div class=\"role-row\" aria-label=\"Available sub-agents\">\n        @for (role of roles; track role.subAgent) {\n          <span [attr.data-fired]=\"called(role.subAgent)\">{{ role.label }}</span>\n        }\n      </div>\n      @if (delegations().length === 0) {\n        <p class=\"empty\">\n          Ask the supervisor to research, write, and critique a task.\n        </p>\n      } @else {\n        <ol>\n          @for (\n            delegation of delegations();\n            track delegation.id;\n            let index = $index\n          ) {\n            <li\n              [attr.data-testid]=\"testIdFor(delegation.subAgent)\"\n              [attr.data-status]=\"delegation.status\"\n            >\n              <strong>{{ index + 1 }}. {{ labelFor(delegation.subAgent) }}</strong>\n              <span>{{ delegation.status }}</span>\n              <p>{{ delegation.task }}</p>\n              <blockquote>{{ delegation.result }}</blockquote>\n            </li>\n          }\n        </ol>\n      }\n    </section>\n  `,\n  styles: `\n    :host {\n      display: block;\n      min-width: 0;\n    }\n    .delegation-log {\n      overflow: hidden;\n      border: 1px solid #d8e0ea;\n      border-radius: 1rem;\n      background: #fff;\n      box-shadow: 0 12px 34px rgb(30 49 73 / 8%);\n    }\n    header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 1rem;\n      padding: 1rem;\n      border-bottom: 1px solid #e2e8f0;\n    }\n    header p,\n    header h1 {\n      margin: 0;\n    }\n    header p {\n      color: #6366f1;\n      font-size: 0.7rem;\n      font-weight: 750;\n      letter-spacing: 0.12em;\n      text-transform: uppercase;\n    }\n    header h1 {\n      margin-top: 0.2rem;\n      color: #152238;\n      font-size: 1.1rem;\n    }\n    header span {\n      color: #64748b;\n      font-size: 0.75rem;\n    }\n    .role-row {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 0.5rem;\n      padding: 0.75rem 1rem;\n      border-bottom: 1px solid #e2e8f0;\n    }\n    .role-row span {\n      padding: 0.3rem 0.55rem;\n      border: 1px solid #cbd5e1;\n      border-radius: 999px;\n      color: #64748b;\n      font-size: 0.72rem;\n    }\n    .role-row span[data-fired=\"true\"] {\n      border-color: #818cf8;\n      color: #3730a3;\n      background: #eef2ff;\n    }\n    .empty {\n      margin: 0;\n      padding: 1rem;\n      color: #64748b;\n      font-size: 0.85rem;\n    }\n    ol {\n      display: grid;\n      gap: 0.75rem;\n      margin: 0;\n      padding: 1rem;\n      list-style: none;\n    }\n    li {\n      padding: 0.8rem;\n      border: 1px solid #e2e8f0;\n      border-radius: 0.75rem;\n      background: #f8fafc;\n    }\n    li > span {\n      float: right;\n      color: #15803d;\n      font-size: 0.7rem;\n      text-transform: uppercase;\n    }\n    li p,\n    blockquote {\n      margin: 0.5rem 0 0;\n      color: #475569;\n      font-size: 0.78rem;\n      line-height: 1.45;\n    }\n    blockquote {\n      padding: 0.65rem;\n      border-radius: 0.5rem;\n      background: #fff;\n    }\n  `,\n})\nexport class DelegationLogComponent {\n  readonly delegations = input.required<Delegation[]>();\n  protected readonly roles = [\n    { subAgent: \"research_agent\" as const, label: \"Researcher\" },\n    { subAgent: \"writing_agent\" as const, label: \"Writer\" },\n    { subAgent: \"critique_agent\" as const, label: \"Critic\" },\n  ];\n\n  protected called(subAgent: SubAgentName): boolean {\n    return this.delegations().some(\n      (delegation) => delegation.subAgent === subAgent,\n    );\n  }\n\n  protected labelFor(subAgent: SubAgentName): string {\n    return SUB_AGENT_META[subAgent].label;\n  }\n\n  /** Resolve a delegation-log identity distinct from transcript tool cards. */\n  protected testIdFor(subAgent: SubAgentName): string {\n    return SUB_AGENT_META[subAgent].delegationTestId;\n  }\n}\n",
  "src/app/features/subagents/subagent-model.ts": "/**\n * Delegation-log model for\n * https://docs.copilotkit.ai/angular/ag2/multi-agent/subagents\n *\n * The page uses `readDelegations` and `SubAgentName` without showing them.\n * This is the sub-agent half of the Angular Showcase's\n * features/agent-state/agent-state-model.ts, unchanged; the planner (`steps`)\n * half belongs to a different demo and is left out.\n */\nexport type SubAgentName =\n  | \"research_agent\"\n  | \"writing_agent\"\n  | \"critique_agent\";\n\nexport interface Delegation {\n  id: string;\n  subAgent: SubAgentName;\n  task: string;\n  status: \"completed\";\n  result: string;\n}\n\n/** Read completed supervisor delegations from append-only agent state. */\nexport function readDelegations(state: unknown): Delegation[] {\n  const delegations = readArraySlot(state, \"delegations\");\n  return delegations.flatMap((candidate) => {\n    if (!isRecord(candidate)) return [];\n    const { id, sub_agent: subAgent, task, status, result } = candidate;\n    if (\n      typeof id !== \"string\" ||\n      !isSubAgentName(subAgent) ||\n      typeof task !== \"string\" ||\n      status !== \"completed\" ||\n      typeof result !== \"string\"\n    ) {\n      return [];\n    }\n    return [{ id, subAgent, task, status, result }];\n  });\n}\n\nfunction readArraySlot(state: unknown, slot: string): unknown[] {\n  if (!isRecord(state)) return [];\n  const value = state[slot];\n  return Array.isArray(value) ? value : [];\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === \"object\" && value !== null;\n}\n\nfunction isSubAgentName(value: unknown): value is SubAgentName {\n  return (\n    value === \"research_agent\" ||\n    value === \"writing_agent\" ||\n    value === \"critique_agent\"\n  );\n}\n",
  "src/app/features/subagents/subagent-renderer-config.ts": "/**\n * `subAgentRendererConfig`, used but not shown by\n * https://docs.copilotkit.ai/angular/ag2/multi-agent/subagents\n *\n * Unchanged from the Angular Showcase's\n * features/agent-state/subagent-renderer-config.ts.\n */\nimport type { RenderToolCallConfig } from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\nimport { SubAgentActivityCard } from \"./subagent-cards\";\nimport type { SubAgentName } from \"./subagent-model\";\n\n/**\n * Build a route-lifetime subagent renderer that also matches runtimes whose\n * assistant messages do not carry an agent identifier.\n */\nexport function subAgentRendererConfig(\n  name: SubAgentName,\n): RenderToolCallConfig<{ task: string }> {\n  return {\n    name,\n    args: z.object({ task: z.string() }),\n    component: SubAgentActivityCard as unknown as RenderToolCallConfig<{\n      task: string;\n    }>[\"component\"],\n  };\n}\n",
  "src/app/features/subagents/subagents-chat.component.ts": "/**\n * \"Rendering a live delegation log\", from\n * https://docs.copilotkit.ai/angular/ag2/multi-agent/subagents\n *\n * The class members between the region markers are the guide's snippet,\n * unchanged. The two fields it reads but does not show are resolved the way\n * the Angular Showcase's agent-state-feature.component.ts resolves them for\n * this demo: `feature` is \"subagents\", and `agentId` is the runtime key the\n * supervisor is registered under in server.ts. Template and layout come from\n * that same showcase component, with its showcase chat host replaced by a\n * plain copilot-chat on the same agent.\n */\nimport { Component, computed } from \"@angular/core\";\nimport {\n  CopilotChat,\n  injectAgentStore,\n  registerRenderToolCall,\n} from \"@copilotkit/angular\";\n\nimport { DelegationLogComponent } from \"./subagent-cards\";\nimport type { SubAgentName } from \"./subagent-model\";\nimport { readDelegations } from \"./subagent-model\";\nimport { subAgentRendererConfig } from \"./subagent-renderer-config\";\n\n@Component({\n  selector: \"app-subagents-chat\",\n  imports: [CopilotChat, DelegationLogComponent],\n  template: `\n    <main class=\"agent-state-page subagents\">\n      <aside aria-label=\"Live supervisor delegation state\">\n        <showcase-delegation-log [delegations]=\"delegations()\" />\n      </aside>\n      <section class=\"chat-surface\" aria-label=\"CopilotKit assistant\">\n        <copilot-chat [agentId]=\"agentId\" />\n      </section>\n    </main>\n  `,\n  styles: `\n    :host {\n      display: block;\n      height: 100%;\n    }\n    .agent-state-page {\n      height: 100%;\n      min-height: 0;\n      background: #eef3f7;\n    }\n    .chat-surface {\n      min-width: 0;\n      height: 100%;\n      background: #fff;\n    }\n    .subagents {\n      display: grid;\n      grid-template-columns: minmax(18rem, 0.85fr) minmax(0, 1.35fr);\n      gap: 1rem;\n      padding: 1rem;\n    }\n    .subagents aside {\n      min-width: 0;\n      overflow: auto;\n    }\n    .subagents .chat-surface {\n      overflow: hidden;\n      border: 1px solid #d8e0ea;\n      border-radius: 1rem;\n    }\n    @media (max-width: 52rem) {\n      .subagents {\n        grid-template-columns: 1fr;\n        grid-template-rows: auto minmax(30rem, 55vh);\n        overflow: auto;\n      }\n    }\n  `,\n})\nexport class SubagentsChatComponent {\n  protected readonly feature = \"subagents\";\n  protected readonly agentId = \"subagents\";\n  // subagents : rendering a live delegation log start\n  private readonly agentStore = injectAgentStore(this.agentId);\n  protected readonly delegations = computed(() =>\n    readDelegations(this.agentStore().state()),\n  );\n\n  constructor() {\n    if (this.feature === \"subagents\") {\n      this.registerSubAgent(\"research_agent\");\n      this.registerSubAgent(\"writing_agent\");\n      this.registerSubAgent(\"critique_agent\");\n    }\n  }\n\n  private registerSubAgent(name: SubAgentName): void {\n    registerRenderToolCall(subAgentRendererConfig(name));\n  }\n  // subagents : rendering a live delegation log end\n}\n",
  "src/app/features/threads/conversations.component.ts": "/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  // Layout lives on the host and in scoped styles, never in the template: the\n  // two element tags below are the guide's sample and stay byte-identical to it.\n  // Without this the host is `display: inline`, so the drawer and chat ignore\n  // the flex row they sit in and the chat shrink-wraps to a narrow column.\n  host: { class: 'flex min-h-0 flex-1 gap-4' },\n  styles: `\n    copilot-threads-drawer {\n      display: block;\n      flex: 0 0 16rem;\n      min-height: 0;\n      overflow-y: auto;\n    }\n    copilot-chat {\n      display: block;\n      flex: 1 1 auto;\n      min-width: 0;\n      min-height: 0;\n    }\n  `,\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n",
  "src/app/features/threads/thread-list.component.ts": "/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\n * list on `injectThreads`, and the drop-in drawer beside a chat.\n */\nimport { Component } from '@angular/core';\n\nimport { ConversationsComponent } from './conversations.component';\nimport { ThreadListComponent } from './thread-list.component';\n\n@Component({\n  selector: 'app-threads-demo',\n  imports: [ThreadListComponent, ConversationsComponent],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <section class=\"rounded-lg border border-slate-200 bg-white p-4\">\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          Headless list — injectThreads\n        </h2>\n        <app-thread-list />\n      </section>\n\n      <section\n        class=\"flex min-h-0 flex-1 flex-col rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          CopilotThreadsDrawer + chat\n        </h2>\n        <div class=\"flex min-h-0 flex-1 gap-4\">\n          <app-conversations />\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class ThreadsDemoComponent {}\n",
  "src/app/features/tools/incident-card.component.ts": "/**\n * \"Let the agent display one of your components\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n *\n * Two deviations from the published snippet, both mechanical:\n * `standalone: true` is dropped — it is the default on Angular v20+ and\n * frontend/AGENTS.md forbids setting it — and the two imports are narrowed to\n * `type` imports, matching weather-card.component.ts.\n *\n * Unlike WeatherCardComponent this renderer never reads `call.result`: a\n * display-only component has no application code behind it, so the tool\n * completes with an empty result and the args are the whole payload.\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype IncidentArgs = { id: string; severity: string };\n\n@Component({\n  selector: 'app-incident-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"in-progress\") {\n      <p>Loading incident…</p>\n    } @else {\n      <article>\n        <strong>{{ call.args.id }}</strong>\n        <span>{{ call.args.severity }}</span>\n      </article>\n    }\n  `,\n})\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\n}\n",
  "src/app/features/tools/tool-feature-model.ts": "/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\nimport { type WritableSignal } from '@angular/core';\nimport { type FrontendToolConfig } from '@copilotkit/angular';\nimport { z } from 'zod';\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = {\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string {\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: 'change_background',\n    description: 'Change the application background to a CSS gradient.',\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n",
  "src/app/features/tools/tools-chat.component.ts": "/**\n * Mounts all three of the guide's frontend-tool paths against one chat.\n *\n * `registerRenderToolCall` — the tool runs on the server (the Agent Framework\n * agent's weather tool) and the browser only renders its call, through\n * WeatherCardComponent.\n *\n * `registerComponent` — display only. `show_incident` has neither a handler\n * nor a tool on the agent: the frontend declares it, CopilotKit forwards it\n * over AG-UI, and the agent calls it purely to put IncidentCardComponent on\n * screen. Core inserts an empty tool result, so the turn completes without an\n * invented result being written into the thread.\n *\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\n * has a handler and no component, so it renders nothing in chat; its result is\n * the page itself changing. The registration is removed when this injector is\n * destroyed.\n *\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\n * that runs in the browser. It is not mounted: it would collide with the\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\n * this repo does not serve.\n *\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n */\nimport { Component, signal } from '@angular/core';\nimport {\n  CopilotSidebar,\n  registerComponent,\n  registerFrontendTool,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport {\n  DEFAULT_BACKGROUND,\n  createBackgroundTool,\n} from './tool-feature-model';\nimport { IncidentCardComponent } from './incident-card.component';\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tools-chat',\n  imports: [CopilotSidebar],\n  template: `\n    <div\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n        <copilot-sidebar />\n\n    </div>\n  `,\n})\nexport class ToolsChatComponent {\n  /** Written by the agent through the change_background handler. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    registerRenderToolCall({\n      name: 'getWeather',\n      args: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n    });\n\n    registerComponent({\n      name: 'show_incident',\n      description: 'Show one incident from the incident table.',\n      parameters: z.object({\n        id: z.string().describe('The incident id, such as INC-4711'),\n        severity: z.string().describe('One of sev1, sev2, sev3'),\n      }),\n      component: IncidentCardComponent,\n    });\n\n    registerFrontendTool(createBackgroundTool(this.background));\n  }\n}\n",
  "src/app/features/tools/weather-card.component.ts": "/**\n * \"Render a tool result\", verbatim.\n * https://docs.copilotkit.ai/angular/ag2/guides/frontend-tools-generative-ui\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: 'app-weather-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n    <p>Tool Call done </p>\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n",
  "src/app/features/webmcp/order-search.component.ts": "// webmcp : angular frontend tool start\n/**\n * \"Angular frontend tool\", verbatim from\n * https://docs.copilotkit.ai/angular/ag2/webmcp\n *\n * The only addition is the `searchOrders` import: the guide calls it without\n * defining it, so ./search-orders.ts is self-defined.\n */\nimport { Component } from \"@angular/core\";\nimport { registerFrontendTool } from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\nimport { searchOrders } from \"./search-orders\";\n\n@Component({\n  selector: \"app-order-search\",\n  standalone: true,\n  template: \"\",\n})\nexport class OrderSearchComponent {\n  constructor() {\n    registerFrontendTool({\n      name: \"searchOrders\",\n      description: \"Search the signed-in user's orders by status\",\n      parameters: z.object({\n        status: z.enum([\"open\", \"shipped\", \"delivered\"]),\n      }),\n      handler: async ({ status }) => {\n        const orders = await searchOrders(status);\n        return JSON.stringify(orders);\n      },\n      webmcp: {\n        annotations: {\n          readOnlyHint: true,\n        },\n      },\n    });\n  }\n}\n// webmcp : angular frontend tool end\n",
  "src/app/features/webmcp/search-orders.ts": "/**\n * SELF-DEFINED — not from the docs.\n *\n * https://docs.copilotkit.ai/angular/ag2/webmcp calls\n * `searchOrders(status)` in both of its examples but never defines it. This is\n * a stand-in with fixed in-memory orders so the handler has something real to\n * return. A real app would call its own orders API here, and enforce\n * authentication and authorization there — WebMCP annotations are hints, not\n * security controls.\n */\nexport type OrderStatus = \"open\" | \"shipped\" | \"delivered\";\n\nexport interface Order {\n  id: string;\n  item: string;\n  status: OrderStatus;\n}\n\nconst ORDERS: readonly Order[] = [\n  { id: \"ord-1001\", item: \"Mechanical keyboard\", status: \"open\" },\n  { id: \"ord-1002\", item: \"USB-C dock\", status: \"shipped\" },\n  { id: \"ord-1003\", item: \"27-inch monitor\", status: \"delivered\" },\n  { id: \"ord-1004\", item: \"Desk lamp\", status: \"open\" },\n];\n\nexport async function searchOrders(status: OrderStatus): Promise<Order[]> {\n  return ORDERS.filter((order) => order.status === status);\n}\n",
  "src/app/features/webmcp/webmcp-chat.component.ts": "/**\n * Mounts the guide's Angular frontend tool beside a chat, so the same\n * `searchOrders` handler can be called two ways: by the CopilotKit agent\n * through the chat, and by a WebMCP-aware browser agent through\n * `document.modelContext`. The panel only reports whether the page has\n * `document.modelContext` at all — without it CopilotKit registers nothing,\n * by design.\n * https://docs.copilotkit.ai/angular/ag2/webmcp\n */\nimport { Component, afterNextRender, signal } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { OrderSearchComponent } from './order-search.component';\n\n@Component({\n  selector: 'app-webmcp-chat',\n  imports: [CopilotChat, OrderSearchComponent],\n  template: `\n    <app-order-search />\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <p>\n          <code>document.modelContext</code>:\n          <strong>{{ available() ? 'available' : 'not available' }}</strong>\n        </p>\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class WebmcpChatComponent {\n  protected readonly available = signal(false);\n\n  constructor() {\n    afterNextRender(() =>\n      this.available.set('modelContext' in document),\n    );\n  }\n}\n",
  "src/app/features/webmcp/webmcp-core-demo.component.ts": "/**\n * Runs the guide's \"WebMCP only, with no agent\" module. Importing ./webmcp\n * creates its CopilotKitCore; no chat, Runtime or agent is involved. The panel\n * lists the tool names that core keeps registered on `document.modelContext`.\n * https://docs.copilotkit.ai/angular/ag2/webmcp\n */\nimport { Component, afterNextRender, signal } from '@angular/core';\n\n@Component({\n  selector: 'app-webmcp-core-demo',\n  template: `\n    <div style=\"padding: 1rem\">\n      <p>\n        <code>document.modelContext</code>:\n        <strong>{{ available() ? 'available' : 'not available' }}</strong>\n      </p>\n      <p>\n        CopilotKitCore created with tools:\n        <code>{{ tools().join(', ') || '—' }}</code>\n      </p>\n    </div>\n  `,\n})\nexport class WebmcpCoreDemoComponent {\n  protected readonly available = signal(false);\n  protected readonly tools = signal<string[]>([]);\n\n  constructor() {\n    afterNextRender(async () => {\n      this.available.set('modelContext' in document);\n      const { copilotkit } = await import('./webmcp');\n      this.tools.set(copilotkit.tools.map((tool) => tool.name));\n    });\n  }\n}\n",
  "src/app/features/webmcp/webmcp.ts": "// webmcp : webmcp only with no agent start\n/**\n * \"WebMCP only, with no agent\", verbatim from\n * https://docs.copilotkit.ai/angular/ag2/webmcp\n *\n * Registers the tool straight on a CopilotKitCore, with no Runtime and no\n * agent. The instance is created when this module is first imported (the\n * /webmcp/core-demo route) and kept alive for the rest of the page's life, as\n * the guide asks. The only addition is the self-defined `searchOrders` import.\n */\nimport { CopilotKitCore } from \"@copilotkit/core\";\nimport { z } from \"zod\";\n\nimport { searchOrders } from \"./search-orders\";\n\nexport const copilotkit = new CopilotKitCore({\n  tools: [\n    {\n      name: \"searchOrders\",\n      description: \"Search the signed-in user's orders by status\",\n      parameters: z.object({\n        status: z.enum([\"open\", \"shipped\", \"delivered\"]),\n      }),\n      handler: async ({ status }) => {\n        const orders = await searchOrders(status);\n        return JSON.stringify(orders);\n      },\n      webmcp: {\n        annotations: {\n          readOnlyHint: true,\n        },\n      },\n    },\n  ],\n});\n// webmcp : webmcp only with no agent end\n",
  "../backend/subagents/subagents.py": "# Copied unchanged from the CopilotKit showcase,\n# showcase/integrations/ag2/src/agents/subagents.py — the source\n# https://docs.copilotkit.ai/angular/ag2/multi-agent/subagents quotes. The\n# guide shows this file only up to the three delegation tools; the\n# `supervisor`, `stream` and `subagents_app` below them are the showcase's own.\n#\n# It imports from `autogen`, which ag2 removed in 1.0 — so it runs in its own\n# uv project pinned to ag2<1.0 (pyproject.toml here), separate from the 1.x\n# weather agent in ../main.py.\n\"\"\"AG2 agent for the Sub-Agents demo.\n\nDemonstrates multi-agent delegation with a visible delegation log.\n\nA top-level \"supervisor\" ConversableAgent orchestrates three specialized\nsub-agents — each itself a ConversableAgent — exposed as supervisor tools:\n\n  - `research_agent`  — gathers facts\n  - `writing_agent`   — drafts prose\n  - `critique_agent`  — reviews drafts\n\nEvery delegation appends an entry to the `delegations` slot in shared\nagent state (via AG2's ContextVariables + ReplyResult), so the UI can\nrender a live \"delegation log\" as the supervisor fans work out and\ncollects results. This is the canonical AG2 sub-agents-as-tools pattern,\nadapted to surface delegation events to the frontend via AG-UI's\nshared-state channel.\n\"\"\"\n\n# @region[supervisor-delegation-tools]\n# @region[subagent-setup]\nimport asyncio\nimport logging\nimport uuid\nfrom textwrap import dedent\nfrom typing import List, Literal\n\nfrom autogen import ConversableAgent, LLMConfig\nfrom autogen.ag_ui import AGUIStream\nfrom autogen.agentchat import ContextVariables, ReplyResult\nfrom autogen.tools import tool\nfrom fastapi import FastAPI\nfrom pydantic import BaseModel, Field\n\nlogger = logging.getLogger(__name__)\n\n\nSubAgentName = Literal[\"research_agent\", \"writing_agent\", \"critique_agent\"]\nDelegationStatus = Literal[\"running\", \"completed\", \"failed\"]\n\n\nclass Delegation(BaseModel):\n    \"\"\"One entry in the delegation log shown by the UI.\"\"\"\n\n    id: str\n    sub_agent: SubAgentName\n    task: str\n    status: DelegationStatus = \"completed\"\n    result: str = \"\"\n\n\nclass SubagentsSnapshot(BaseModel):\n    \"\"\"Shape of the shared `delegations` state slot rendered by the UI.\"\"\"\n\n    delegations: List[Delegation] = Field(default_factory=list)\n\n\n# ---------------------------------------------------------------------------\n# Sub-agents (real ConversableAgents under the hood)\n# ---------------------------------------------------------------------------\n#\n# Each sub-agent is its own LLM ConversableAgent with a focused system\n# prompt. They don't share memory or tools with the supervisor — the\n# supervisor only sees what each sub-agent's final reply produces.\n\n_SUB_LLM_CONFIG = LLMConfig({\"model\": \"gpt-5-mini\", \"stream\": False})\n\n_research_agent = ConversableAgent(\n    name=\"research_sub_agent\",\n    system_message=dedent(\n        \"\"\"\n        You are a research sub-agent. Given a topic, produce a concise\n        bulleted list of 3-5 key facts. No preamble, no closing.\n        \"\"\"\n    ).strip(),\n    llm_config=_SUB_LLM_CONFIG,\n    human_input_mode=\"NEVER\",\n    max_consecutive_auto_reply=1,\n)\n\n_writing_agent = ConversableAgent(\n    name=\"writing_sub_agent\",\n    system_message=dedent(\n        \"\"\"\n        You are a writing sub-agent. Given a brief and optional source\n        facts, produce a polished 1-paragraph draft. Be clear and\n        concrete. No preamble.\n        \"\"\"\n    ).strip(),\n    llm_config=_SUB_LLM_CONFIG,\n    human_input_mode=\"NEVER\",\n    max_consecutive_auto_reply=1,\n)\n\n_critique_agent = ConversableAgent(\n    name=\"critique_sub_agent\",\n    system_message=dedent(\n        \"\"\"\n        You are an editorial critique sub-agent. Given a draft, produce\n        2-3 crisp, actionable critiques. No preamble.\n        \"\"\"\n    ).strip(),\n    llm_config=_SUB_LLM_CONFIG,\n    human_input_mode=\"NEVER\",\n    max_consecutive_auto_reply=1,\n)\n# @endregion[subagent-setup]\n\n\nasync def _invoke_sub_agent(sub_agent: ConversableAgent, task: str) -> str:\n    \"\"\"Run a sub-agent on `task` and return its final reply text.\n\n    `generate_reply` produces a single LLM completion against a one-shot\n    user message. AG2's ``generate_reply`` is synchronous and performs a\n    blocking LLM round-trip, so we offload it to a worker thread to keep\n    the asyncio event loop responsive while the call is in flight.\n    \"\"\"\n    reply = await asyncio.to_thread(\n        sub_agent.generate_reply,\n        messages=[{\"role\": \"user\", \"content\": task}],\n    )\n    if reply is None:\n        return \"\"\n    if isinstance(reply, dict):\n        # ConversableAgent.generate_reply may return {\"content\": \"...\"}.\n        return str(reply.get(\"content\") or \"\")\n    return str(reply)\n\n\ndef _load_snapshot(context_variables: ContextVariables) -> SubagentsSnapshot:\n    \"\"\"Best-effort load of the SubagentsSnapshot from context variables.\n\n    Logs at WARNING when state fails validation so silent corruption is\n    visible in server logs instead of degrading to an empty snapshot\n    without a trace.\n    \"\"\"\n    data = context_variables.data or {}\n    try:\n        return SubagentsSnapshot.model_validate(data)\n    except Exception as exc:\n        logger.warning(\n            \"subagents: failed to validate SubagentsSnapshot from context \"\n            \"variables (%s: %s); falling back to empty snapshot\",\n            exc.__class__.__name__,\n            exc,\n        )\n        return SubagentsSnapshot()\n\n\ndef _record_delegation(\n    context_variables: ContextVariables,\n    sub_agent: SubAgentName,\n    task: str,\n    result: str,\n    status: DelegationStatus = \"completed\",\n) -> ReplyResult:\n    \"\"\"Append a delegation entry to shared state and return ReplyResult.\"\"\"\n    snapshot = _load_snapshot(context_variables)\n    snapshot.delegations.append(\n        Delegation(\n            id=str(uuid.uuid4()),\n            sub_agent=sub_agent,\n            task=task,\n            status=status,\n            result=result,\n        )\n    )\n    context_variables.update(snapshot.model_dump())\n    return ReplyResult(\n        message=result,\n        context_variables=context_variables,\n    )\n\n\nasync def _run_delegation(\n    context_variables: ContextVariables,\n    sub_agent_name: SubAgentName,\n    sub_agent: ConversableAgent,\n    task: str,\n) -> ReplyResult:\n    \"\"\"Invoke a sub-agent and record the outcome (completed or failed).\n\n    If the underlying ``generate_reply`` raises (transport error, quota,\n    SDK bug, ...), we record the delegation with ``status='failed'`` and\n    return a sane ReplyResult so the supervisor can recover instead of\n    crashing the turn. The full traceback is logged server-side; the\n    user-facing ``result`` text only mentions the exception class to\n    avoid leaking internals.\n    \"\"\"\n    try:\n        result = await _invoke_sub_agent(sub_agent, task)\n    except Exception as exc:\n        logger.exception(\n            \"subagents: sub-agent %s failed while handling task\", sub_agent_name\n        )\n        failure_message = (\n            f\"sub-agent call failed: {exc.__class__.__name__} (see server logs)\"\n        )\n        return _record_delegation(\n            context_variables,\n            sub_agent_name,\n            task,\n            failure_message,\n            status=\"failed\",\n        )\n\n    return _record_delegation(\n        context_variables,\n        sub_agent_name,\n        task,\n        result,\n        status=\"completed\",\n    )\n\n\n# ---------------------------------------------------------------------------\n# Supervisor tools (each tool delegates to one sub-agent)\n# ---------------------------------------------------------------------------\n\n\n# Each @tool wraps a sub-agent invocation. The supervisor LLM \"calls\"\n# these tools to delegate work; each call asynchronously runs the\n# matching sub-agent, records the delegation into shared state via\n# ContextVariables, and returns a ReplyResult the supervisor reads as\n# its tool output on the next step.\n@tool()\nasync def research_agent(\n    context_variables: ContextVariables,\n    task: str,\n) -> ReplyResult:\n    \"\"\"Delegate a research task to the research sub-agent.\n\n    Use for: gathering facts, background, definitions, statistics. Returns\n    a bulleted list of key facts.\n\n    Args:\n        task: The specific research question or topic to investigate.\n    \"\"\"\n    return await _run_delegation(\n        context_variables, \"research_agent\", _research_agent, task\n    )\n\n\n@tool()\nasync def writing_agent(\n    context_variables: ContextVariables,\n    task: str,\n) -> ReplyResult:\n    \"\"\"Delegate a drafting task to the writing sub-agent.\n\n    Use for: producing a polished paragraph, draft, or summary. Pass\n    relevant facts from prior research inside ``task``.\n\n    Args:\n        task: The brief plus any relevant facts the writer should use.\n    \"\"\"\n    return await _run_delegation(\n        context_variables, \"writing_agent\", _writing_agent, task\n    )\n\n\n@tool()\nasync def critique_agent(\n    context_variables: ContextVariables,\n    task: str,\n) -> ReplyResult:\n    \"\"\"Delegate a critique task to the critique sub-agent.\n\n    Use for: reviewing a draft and suggesting concrete improvements.\n\n    Args:\n        task: The draft to critique (paste it directly into ``task``).\n    \"\"\"\n    return await _run_delegation(\n        context_variables, \"critique_agent\", _critique_agent, task\n    )\n\n\n# @endregion[supervisor-delegation-tools]\n\n\n# ---------------------------------------------------------------------------\n# Supervisor (the agent we export)\n# ---------------------------------------------------------------------------\n\nsupervisor = ConversableAgent(\n    name=\"supervisor\",\n    system_message=dedent(\n        \"\"\"\n        You are a supervisor agent that coordinates three specialized\n        sub-agents to produce high-quality deliverables.\n\n        Available sub-agents (call them as tools):\n          - research_agent: gathers facts on a topic.\n          - writing_agent: turns facts + a brief into a polished draft.\n          - critique_agent: reviews a draft and suggests improvements.\n\n        For most non-trivial user requests, delegate in sequence:\n        research -> write -> critique. Pass the relevant facts/draft\n        through the `task` argument of each tool. Keep your own messages\n        short — explain the plan once, delegate, then return a concise\n        summary once done. The UI shows the user a live log of every\n        sub-agent delegation, so don't repeat sub-agent output verbatim\n        in your final reply — just summarize.\n        \"\"\"\n    ).strip(),\n    llm_config=LLMConfig({\"model\": \"gpt-5-mini\", \"stream\": True}),\n    human_input_mode=\"NEVER\",\n    # Limit supervisor steps to bound delegation fan-out.\n    max_consecutive_auto_reply=8,\n    functions=[research_agent, writing_agent, critique_agent],\n)\n\nstream = AGUIStream(supervisor)\nsubagents_app = FastAPI()\nsubagents_app.mount(\"\", stream.build_asgi())\n",
  "../backend/subagents/main.py": "\"\"\"\nServes the showcase's Sub-Agents supervisor (subagents.py) for the Angular harness.\n\nMounted at `/subagents`, as in the showcase's agent_server.py\n(`app.mount(\"/subagents\", subagents_app)`). The runtime in\nfrontend/server.ts points at `/subagents/` — Starlette redirects the\nslash-less form.\n\"\"\"\nfrom dotenv import load_dotenv\n\n# Before importing the agent: subagents.py builds its LLMConfigs at import\n# time, and they need OPENAI_API_KEY. Walks up from here, so the repo-root .env\n# or backend/.env is found.\nload_dotenv()\n\nfrom fastapi import FastAPI  # noqa: E402\n\nfrom subagents import subagents_app  # noqa: E402\n\napp = FastAPI()\napp.mount(\"/subagents\", subagents_app)\n\n\nif __name__ == \"__main__\":\n    import uvicorn\n\n    uvicorn.run(\"main:app\", host=\"0.0.0.0\", port=8001, reload=True)\n",
  "../backend/subagents/pyproject.toml": "[project]\nname = \"subagents\"\nversion = \"0.1.0\"\ndescription = \"AG2 Sub-Agents supervisor, from the CopilotKit showcase, served over AG-UI for the Angular CopilotKit harness.\"\nrequires-python = \">=3.10,<3.15\"\n# The showcase's pin (showcase/integrations/ag2/requirements.txt): ag2 1.0\n# renamed `autogen` to `ag2`, and subagents.py imports `autogen`.\ndependencies = [\n    \"ag2[openai,ag-ui]>=0.9.0,<1.0.0\",\n    \"fastapi>=0.115.0\",\n    \"python-dotenv>=1.0.0\",\n    \"uvicorn>=0.40.0\",\n]\n\n[tool.uv]\npackage = false\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
